#!/usr/bin/env bash
# Regenerate tools/wasm-tools/WasmTools/Help.lean (upstream help texts, verbatim) from the
# pinned wasm-tools 1.262.0.  Usage: tools/wasm-tools/tests/gen-help.sh
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
source "$here/pins.sh"
wt_require_upstream
python3 -I - "$WT_UPSTREAM" "$here/../WasmTools/Help.lean" parse print <<'PY'
import json, subprocess, sys
w, out, cmds = sys.argv[1], sys.argv[2], sys.argv[3:]
parts = ['/-! Help texts of upstream wasm-tools 1.262.0, verbatim (generated by\n'
         '`tools/wasm-tools/tests/gen-help.sh`; do not edit). -/\n\nnamespace WasmTools.Help\n']
for c in cmds:
    for flag, nm in [('-h', 'short'), ('--help', 'long')]:
        t = subprocess.run([w, c, flag], capture_output=True, text=True).stdout
        parts.append(f'def {c}_{nm} : String := {json.dumps(t, ensure_ascii=False)}\n')
parts.append('\nend WasmTools.Help\n')
open(out, 'w').write('\n'.join(parts))
PY
